import os, re, json

d = os.environ['RLM_SESSION_DIR']
session_file = d.replace('session-artifacts', 'sessions') + '.jsonl'

with open(session_file, 'r') as f:
    lines = f.readlines()

# Look at all user messages and assistant messages in detail
for i, line in enumerate(lines):
    try:
        entry = json.loads(line)

        if entry.get('type') == 'message':
            msg = entry.get('message', {})
            role = msg.get('role', '')

            # Check for user or assistant messages with text content
            if role in ('user', 'assistant'):
                content = msg.get('content', [])
                if content and isinstance(content, list):
                    # Get first text item
                    text_parts = []
                    for c in content:
                        if isinstance(c, dict):
                            if 'text' in c:
                                text_parts.append(('text', c['text'][:200]))
                            elif 'thinking' in c:
                                text_parts.append(('thinking', c['thinking'][:200]))

                    if text_parts:
                        role_label = 'USER' if role == 'user' else 'ASSISTANT'
                        tag, snippet = text_parts[0]

                        # Print if it looks important (contains key words or is a tool call)
                        keywords = ['Test input', 'Demo pair', 'Wrong attempts', 'Reply with exactly one action', '{\"action\":']
                        if any(kw in snippet for kw in keywords) or tag == 'toolCall':
                            print(f"[{i}] {role_label}: {tag} - {snippet}")

    except json.JSONDecodeError:
        pass

print("\n\n=== Done scanning ===")

